<script setup lang="ts">
import AccountImageInput from '../../components/console/AccountImageInput.vue'
import PackageThumbnail from '../../components/tenant/PackageThumbnail.vue'
import AdminConsole from '../../components/console/AdminConsole.vue'
import ConsoleDrawer from '../../components/console/ConsoleDrawer.vue'
import ConsoleDiscardChangesDialog from '../../components/console/ConsoleDiscardChangesDialog.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleDataTable from '@orangezh1/qisvc-console-ui/components/ConsoleDataTable'
definePageMeta({layout:'tenant',key:route=>route.path})
type Tier={id:string;image?:string|null;name?:string;priceCents?:number;points?:number;giftPoints?:number;amountCents?:number;giftCents?:number;enabled:boolean;sort:number}
type Config={points:Tier[];balance:{tiers:Tier[];customEnabled:boolean;minCents:number;maxCents:number}}
type View={applicationKey:string;version:number;canWrite:boolean;config:Config}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/recharge',toast=useToast()
const initial=await useAsyncData<View>('recharge:'+auth.session.value?.id+':'+tenantId,(_,{signal})=>auth.api<View>(endpoint,'GET',undefined,{signal}))
const data=ref<View|null>(initial.data.value||null),error=ref(initial.error.value?.message||''),kind=useRouteTab<string>('points',['points','balance']),action=ref(''),mutation=ref(''),editorOpen=ref(false),editing=ref<Tier|null>(null),formError=ref(''),imageBusy=ref(false),form=reactive({name:'',image:null as string|null,price:'',points:'',gift:'',sort:0,enabled:true}),baseline=ref('')
const custom=reactive({enabled:data.value?.config.balance.customEnabled||false,min:money(data.value?.config.balance.minCents||1),max:money(data.value?.config.balance.maxCents||100000000)}),customBaseline=ref(JSON.stringify(custom))
const dirty=computed(()=>editorOpen.value&&baseline.value!==JSON.stringify(form)||customBaseline.value!==JSON.stringify(custom)),discard=useDiscardChanges(()=>!!mutation.value||imageBusy.value),lifetime=new AbortController();let controller:AbortController|undefined,sequence=0,disposed=false
const tiers=computed(()=>[...(kind.value==='points'?data.value?.config.points||[]:data.value?.config.balance.tiers||[])].sort((a,b)=>a.sort-b.sort||a.id.localeCompare(b.id)))
const columns=computed(()=>[{id:'name',header:kind.value==='points'?'套餐名称':'充值金额'},{id:'amount',header:kind.value==='points'?'售价 / 到账积分':'赠送金额'},{accessorKey:'sort',header:'排序'},{id:'enabled',header:'状态'},{id:'actions',header:'操作'}])
function money(value:number){return Math.trunc(value/100)+'.'+String(value%100).padStart(2,'0')}
function cents(value:string,zero=false){if(!/^(0|[1-9]\d{0,6})(\.\d{1,2})?$/.test(value))throw Error('金额最多两位小数');const [whole,fraction='']=value.split('.'),amount=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(amount<(zero?0:1)||amount>100000000)throw Error('金额超出允许范围');return amount}
function sync(value:View){data.value=value;Object.assign(custom,{enabled:value.config.balance.customEnabled,min:money(value.config.balance.minCents),max:money(value.config.balance.maxCents)});customBaseline.value=JSON.stringify(custom)}
async function load(source='refresh'){
 if(mutation.value||disposed)return;controller?.abort();controller=new AbortController();const current=++sequence;action.value=source
 try{const value=await auth.api<View>(endpoint,'GET',undefined,{signal:AbortSignal.any([controller.signal,lifetime.signal])});if(!disposed&&current===sequence){sync(value);error.value=''}}catch(e:any){if(!disposed&&current===sequence)error.value=e.message||'读取失败'}finally{if(!disposed&&current===sequence)action.value=''}
}
function refresh(){if(dirty.value){discard.request(()=>{editorOpen.value=false;void load()});return}void load()}
function edit(row:Tier|null=null){if(mutation.value||imageBusy.value||!data.value?.canWrite)return;editing.value=row;Object.assign(form,{name:row?.name||'',image:row?.image||null,price:row?money(row.priceCents??row.amountCents??0):'',points:row?.points?.toString()||'',gift:kind.value==='points'?String(row?.giftPoints||0):money(row?.giftCents||0),sort:row?.sort||0,enabled:row?.enabled??true});formError.value='';baseline.value=JSON.stringify(form);editorOpen.value=true}
function close(){if(mutation.value||imageBusy.value)return;if(baseline.value!==JSON.stringify(form)){discard.request(()=>{editorOpen.value=false});return}editorOpen.value=false}
function discardDrafts(){editorOpen.value=false;editing.value=null;Object.assign(form,{name:'',image:null,price:'',points:'',gift:'',sort:0,enabled:true});baseline.value=JSON.stringify(form);formError.value='';if(data.value)sync(data.value)}
async function persist(config:Config,source:string){if(!data.value||mutation.value||imageBusy.value||disposed)return false;controller?.abort();sequence++;action.value='';mutation.value=source;error.value=''
 try{const result=await auth.api<View>(endpoint+'/'+encodeURIComponent(data.value.applicationKey),'PUT',{version:data.value.version,config},{signal:lifetime.signal});if(!disposed){const preserve=source!=='custom'&&customBaseline.value!==JSON.stringify(custom),draft={...custom},oldBaseline=customBaseline.value;sync(result);if(preserve){Object.assign(custom,draft);customBaseline.value=oldBaseline}toast.add({title:'充值配置已保存',color:'success'})}return true}catch(e:any){if(!disposed){if(source==='save')formError.value=e.message||'保存失败';else error.value=e.message||'保存失败'}return false}finally{if(!disposed)mutation.value=''}
}
async function save(){if(!data.value||mutation.value||imageBusy.value)return;try{const price=cents(form.price),sort=Number(form.sort);if(!Number.isInteger(sort)||sort<0||sort>100000)throw Error('排序须为 0–100000 的整数');let row:Tier={id:editing.value?.id||crypto.randomUUID(),image:form.image,sort,enabled:form.enabled};if(kind.value==='points'){const points=Number(form.points),gift=Number(form.gift);if(!form.name.trim()||!Number.isSafeInteger(points)||points<1||points>100000000||!Number.isSafeInteger(gift)||gift<0||gift>100000000)throw Error('请填写名称、正整数积分和非负赠送积分');row={...row,name:form.name.trim(),priceCents:price,points,giftPoints:gift}}else row={...row,amountCents:price,giftCents:cents(form.gift,true)};const config=structuredClone(toRaw(data.value.config)),rows=kind.value==='points'?config.points:config.balance.tiers,index=rows.findIndex(r=>r.id===row.id);if(index<0)rows.push(row);else rows[index]=row;if(await persist(config,'save'))editorOpen.value=false}catch(e:any){formError.value=e.message}}
async function toggle(row:Tier){if(!data.value||mutation.value)return;const config=structuredClone(toRaw(data.value.config)),rows=kind.value==='points'?config.points:config.balance.tiers;rows.find(r=>r.id===row.id)!.enabled=!row.enabled;await persist(config,'status:'+row.id)}
async function saveCustom(){if(!data.value||mutation.value)return;try{const config=structuredClone(toRaw(data.value.config));config.balance={...config.balance,customEnabled:custom.enabled,minCents:cents(custom.min),maxCents:cents(custom.max)};if(config.balance.minCents>config.balance.maxCents)throw Error('最低金额不能超过最高金额');await persist(config,'custom')}catch(e:any){error.value=e.message}}
usePageLeaveGuard(()=>{if(mutation.value||imageBusy.value)return false;if(dirty.value)return discard.decide(discardDrafts);discardDrafts()})
onBeforeUnmount(()=>{disposed=true;sequence++;controller?.abort();lifetime.abort()})
</script>
<template><AdminConsole :refreshing="action==='refresh'" @refresh="refresh"><div class="space-y-5">
 <ConsolePageHeading title="充值配置"><template #actions><UButton v-if="data?.canWrite" icon="i-lucide-plus" :disabled="!!mutation" @click="edit()">{{kind==='points'?'新建积分套餐':'新建充值档位'}}</UButton></template></ConsolePageHeading>
 <UAlert v-if="error" color="error" :title="error"><template #actions><UButton :loading="action==='retry'" :disabled="!!mutation" @click="load('retry')">重试</UButton></template></UAlert>
 <div role="tablist" class="flex gap-3"><UButton v-for="tab in [{value:'points',label:'积分套餐'},{value:'balance',label:'余额充值'}]" :key="tab.value" role="tab" :aria-selected="kind===tab.value" :variant="kind===tab.value?'solid':'outline'" :disabled="!!mutation||imageBusy" @click="kind=tab.value">{{tab.label}}</UButton></div>
 <ConsoleDataTable :data="tiers" :columns="columns" :page-size="20" empty-title="暂无充值档位" empty-description="配置并保存后，客户端可读取已启用的档位。" min-table-width="650px">
  <template #name-cell="{row}"><div class="flex items-center gap-3"><PackageThumbnail :image="row.original.image" :name="row.original.name||'余额充值'"/><span class="font-medium">{{kind==='points'?row.original.name:'¥ '+money(row.original.amountCents)}}</span></div></template>
  <template #amount-cell="{row}"><div v-if="kind==='points'"><p>¥ {{money(row.original.priceCents)}}</p><p class="text-xs text-muted">{{row.original.points}} 积分<span v-if="row.original.giftPoints"> + 赠 {{row.original.giftPoints}}</span></p></div><span v-else>¥ {{money(row.original.giftCents)}}</span></template>
  <template #enabled-cell="{row}"><UBadge :color="row.original.enabled?'success':'neutral'" variant="subtle">{{row.original.enabled?'启用':'停用'}}</UBadge></template>
  <template #actions-cell="{row}"><div v-if="data?.canWrite" class="flex gap-3 whitespace-nowrap"><UButton variant="link" class="px-0" :disabled="!!mutation" @click="edit(row.original)">编辑</UButton><UButton variant="link" class="px-0" :loading="mutation==='status:'+row.original.id" :disabled="!!mutation" @click="toggle(row.original)">{{row.original.enabled?'停用':'启用'}}</UButton></div></template>
 </ConsoleDataTable>
 <form v-if="kind==='balance'&&data" class="rounded-xl border border-default bg-default p-6 space-y-5" @submit.prevent="saveCustom"><h2 class="font-semibold">自定义金额</h2><ConsoleSettingsField label="允许自定义"><USwitch v-model="custom.enabled" :disabled="!data.canWrite||!!mutation"/></ConsoleSettingsField><ConsoleSettingsField label="最低金额（元）"><ConsoleInput v-model="custom.min" inputmode="decimal" :disabled="!data.canWrite||!!mutation"/></ConsoleSettingsField><ConsoleSettingsField label="最高金额（元）"><ConsoleInput v-model="custom.max" inputmode="decimal" :disabled="!data.canWrite||!!mutation"/></ConsoleSettingsField><p class="text-xs text-muted">自定义金额不赠送余额。余额充值仅支持外部支付，不能使用账户余额。</p><ConsoleFormActions class="border-t border-default pt-5"><UButton type="submit" :loading="mutation==='custom'" :disabled="!data.canWrite||!!mutation||customBaseline===JSON.stringify(custom)">保存</UButton></ConsoleFormActions></form>
 <ConsoleDrawer :open="editorOpen" :title="editing?'编辑充值档位':'新建充值档位'" :dismissible="!mutation&&!imageBusy" @update:open="!$event&&close()"><template #body><form id="recharge-form" class="space-y-5" @submit.prevent="save"><UAlert v-if="formError" color="error" :title="formError"/><ConsoleSettingsField label="套餐封面"><AccountImageInput v-model="form.image" label="套餐封面" portal="tenant" :endpoint="'/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data?.applicationKey||'')" fit="contain" :image-size="512" fallback="" :disabled="!!mutation" @busy="imageBusy=$event"/></ConsoleSettingsField><ConsoleSettingsField v-if="kind==='points'" label="套餐名称"><ConsoleInput v-model="form.name" required :maxlength="64" :disabled="!!mutation"/></ConsoleSettingsField><ConsoleSettingsField :label="kind==='points'?'售价（元）':'充值金额（元）'"><ConsoleInput v-model="form.price" inputmode="decimal" required :disabled="!!mutation"/></ConsoleSettingsField><ConsoleSettingsField v-if="kind==='points'" label="基础积分"><ConsoleInput v-model="form.points" type="number" min="1" step="1" required :disabled="!!mutation"/></ConsoleSettingsField><ConsoleSettingsField :label="kind==='points'?'赠送积分':'赠送余额（元）'"><ConsoleInput v-model="form.gift" :type="kind==='points'?'number':'text'" :inputmode="kind==='points'?'numeric':'decimal'" min="0" step="1" required :disabled="!!mutation"/></ConsoleSettingsField><ConsoleSettingsField label="排序"><ConsoleInput v-model="form.sort" type="number" min="0" max="100000" step="1" :disabled="!!mutation"/></ConsoleSettingsField><ConsoleSettingsField label="状态"><USwitch v-model="form.enabled" :label="form.enabled?'启用':'停用'" :disabled="!!mutation"/></ConsoleSettingsField><p class="text-xs text-muted">到账资产长期有效。保存只影响新订单，历史价格与赠送按下单快照处理。</p></form></template><template #footer><ConsoleFormActions><UButton variant="outline" color="neutral" :disabled="!!mutation" @click="close">取消</UButton><UButton form="recharge-form" type="submit" :loading="mutation==='save'" :disabled="!!mutation||imageBusy">保存</UButton></ConsoleFormActions></template></ConsoleDrawer>
 <ConsoleDiscardChangesDialog :controller="discard"/>
</div></AdminConsole></template>
